WITH prev_events AS (SELECT *, LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) AS prev_txn_time FROM transactions), flagged AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL '60' DAY THEN 1 ELSE 0 END AS is_new_session FROM prev_events), sessions_transactions AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT CASE WHEN amount >= 4400 THEN 'LARGE' ELSE 'SMALL' END AS amount_tier, CASE WHEN session_no >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS session_no_tier, CASE WHEN is_new_session >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END AS is_new_session_tier, PERCENTILE_APPROX(session_no, 0.5) AS session_no_p50, ROUND(SUM(session_no) / NULLIF(COUNT(CASE WHEN merchant = 'Amazon' THEN 1 END), 0), 2) AS session_no_per_amazon, ROUND(AVG(is_new_session), 2) AS avg_is_new_session, PERCENTILE_APPROX(session_no, 0.9) AS session_no_p90, COUNT(*) FILTER (WHERE merchant = 'Shell') AS shell_rows FROM sessions_transactions GROUP BY CUBE (CASE WHEN amount >= 4400 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN session_no >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN is_new_session >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END) HAVING shell_rows < 1
